package io.coolbox.datastructures;
import com.sun.jna.ptr.LongByReference; import io.coolbox.internal.NativeHandle; import java.util.*;
/** Float-vector nearest-neighbor cover tree (Python: {@code data_structures.Float64CoverTree}). */
public final class Float64CoverTree extends NativeHandle {
 private final int dimensions;
 public Float64CoverTree(int dimensions){this(dimensions,CoverTreeKind.STANDARD);} public Float64CoverTree(int dimensions,CoverTreeKind kind){super(DataStructuresNative.INSTANCE.coolbox_ds_cover_tree_new(kind==CoverTreeKind.FASTER?1:0,checkedDimensions(dimensions)),DataStructuresNative.INSTANCE::coolbox_ds_cover_tree_free);this.dimensions=dimensions;}
 private static int checkedDimensions(int d){if(d<=0)throw new IllegalArgumentException("dimensions must be positive");return d;} public int dimensions(){return dimensions;} public void build(double[][] rows){double[] flat=flatten(rows);DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_cover_tree_build(handle(),flat,rows.length,dimensions));} public void insert(double[] item){check(item);DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_cover_tree_insert(handle(),item,dimensions));} public void clear(){DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_cover_tree_clear(handle()));} public long size(){return DataStructuresNative.INSTANCE.coolbox_ds_cover_tree_size(handle());} public boolean validate(){return DataStructuresNative.INSTANCE.coolbox_ds_cover_tree_validate(handle())!=0;}
 public List<CoverTreeNeighbor> query(double[] query){return query(query,1,null);} public List<CoverTreeNeighbor> query(double[] query,int k,Double radius){check(query);if(k<0)throw new IllegalArgumentException("k cannot be negative");LongByReference count=new LongByReference();double r=radius==null?0:radius;int use=radius==null?0:1;DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_cover_tree_query(handle(),query,dimensions,k,r,use,count,null,null,null,0));int n=Math.toIntExact(count.getValue());long[] indices=new long[n];double[] distances=new double[n],items=new double[Math.multiplyExact(n,dimensions)];if(n>0)DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_cover_tree_query(handle(),query,dimensions,k,r,use,count,indices,distances,items,n));List<CoverTreeNeighbor> out=new ArrayList<>();for(int i=0;i<n;i++)out.add(new CoverTreeNeighbor(indices[i],distances[i],Arrays.copyOfRange(items,i*dimensions,(i+1)*dimensions)));return List.copyOf(out);}
 private void check(double[] v){if(v.length!=dimensions)throw new IllegalArgumentException("vector dimensions do not match configured dimensions");} private double[] flatten(double[][] rows){double[] out=new double[Math.multiplyExact(rows.length,dimensions)];for(int i=0;i<rows.length;i++){check(rows[i]);System.arraycopy(rows[i],0,out,i*dimensions,dimensions);}return out;}
}
